css:
.pr { max-width: 62ch; }
.pr > *, .pr > .os-rich > * { margin: 0; max-width: 62ch; }
.pr > .os-rich { max-width: none; }
.pr > * + *, .pr > .os-rich > * + * { margin-top: 1.1em; }
.pr ul, .pr ol { padding-left: 1.2rem; }
.pr li { margin-top: .5em; }
.pr h2 { margin-top: 1.8em; font-size: clamp(1.6rem, 1.1rem + 1.6vw, 2.3rem); line-height: 1.08; }
.pr h2:last-child { font-size: clamp(2rem, 1rem + 3.4vw, 3.8rem); line-height: 1.12; max-width: 18ch; margin-top: clamp(2.2rem, 5vw, 3.6rem); }
.pr h3 { margin-top: 1.2em; font-size: 1.25rem; }
